package com.vandorlabs.neoforge.screen;
import net.minecraft.client.Minecraft;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.ClientTickEvent;
import net.neoforged.neoforge.network.PacketDistributor;
/** Actual ClientLevel update-packet reconstruction, including old-format negative and repeated updates. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class ScreenPowerClientChecks {
 private static int stage,ticks,wait,checks;private static long revision;
 private static void need(boolean value,String reason){checks++;if(!value)throw new IllegalStateException("Screen projection client stage="+stage+": "+reason);}
 private static void send(int operation){PacketDistributor.sendToServer(new ScreenPowerClientFixture.Mode(operation));}
 @SubscribeEvent public static void tick(ClientTickEvent.Post event){if(!ScreenPowerClientFixture.enabled())return;var mc=Minecraft.getInstance();if(mc.screen instanceof net.minecraft.client.gui.screens.AccessibilityOnboardingScreen screen){screen.onClose();return;}if(stage==6&&mc.level==null){System.out.println("[vandorlabs][screen-power-client] client PASS checks="+checks+" actual S2C physical power/legacy-negative/restoration/repeat/withdraw; renderer and player input remain separate");stage=7;mc.stop();return;}if(mc.level==null||mc.player==null||mc.gameMode==null)return;need(++ticks<900,"bounded timeout mode="+mc.gameMode.getPlayerMode()+" slot="+mc.player.getInventory().selected+" main="+mc.player.getMainHandItem()+" pos="+mc.player.position());if(!(mc.level.getBlockEntity(ScreenPowerClientFixture.ROOT) instanceof NativeScreenEntity tile))return;switch(stage){case 0->{if(mc.gameMode.getPlayerMode()!=GameType.CREATIVE||mc.player.getInventory().selected!=0||!mc.player.getMainHandItem().isEmpty()||!mc.player.getOffhandItem().isEmpty()||mc.player.position().distanceToSqr(.5,96,-3)>.01||tile.visual().effectivePower()!=15)return;need(tile.screenSettings().channelLevel()==0&&tile.visual().appearance().effectiveMode==1&&mc.level.getBlockState(ScreenPowerClientFixture.ROOT).getLightEmission(mc.level,ScreenPowerClientFixture.ROOT)==11,"actual physical power decoded independently of channels");revision=tile.visual().geometryRevision();send(0);stage=1;}case 1->{if(tile.visual().effectivePower()!=0)return;need(tile.visual().appearance().effectiveMode==0,"old packet lacking sample reproduces dark client despite powered server");send(1);stage=2;}case 2->{if(tile.visual().effectivePower()!=15)return;need(tile.visual().appearance().effectiveMode==1&&tile.visual().geometryRevision()==revision,"authoritative projection restores client without geometry invalidation");send(2);wait=ticks;stage=3;}case 3->{if(ticks<wait+10)return;need(tile.visual().effectivePower()==15&&tile.visual().geometryRevision()==revision,"repeated actual packet retains coherent state");send(3);stage=4;}case 4->{if(tile.visual().effectivePower()!=0)return;need(tile.visual().appearance().effectiveMode==0&&tile.visual().geometryRevision()==revision,"actual neighbor withdrawal reaches client");send(4);stage=5;}case 5->{if(!mc.level.getBlockState(ScreenPowerClientFixture.ACK).is(Blocks.STONE))return;if(!ScreenPreparedClientPowerChecks.tick(mc,tile))return;mc.level.disconnect();mc.disconnect();stage=6;}default->{}}}
}
